function c(e){if(!e)return null;let n;try{if(Array.isArray(e)){const[s,o,a,r=0,u=0,l=0]=e;n=new Date(s,o-1,a,r,u,l)}else typeof e=="string"?e.includes("T")?n=new Date(e):n=new Date(e.replace(" ","T")):typeof e=="object"&&e!==null?e.year&&e.month&&e.day?n=new Date(e.year,e.month-1,e.day,e.hour||0,e.minute||0,e.second||0):n=new Date(e):n=new Date(e);return isNaN(n.getTime())?(console.warn("日期解析失败:",e),null):n}catch(s){return console.error("日期解析错误:",e,s),null}}function f(e){const n=c(e);if(!n)return"";const o=new Date-n,a=60*1e3,r=60*a,u=24*r,l=7*u;return o<a?"刚刚":o<r?`${Math.floor(o/a)}分钟前`:o<u?`${Math.floor(o/r)}小时前`:o<l?`${Math.floor(o/u)}天前`:n.toLocaleDateString("zh-CN",{year:"numeric",month:"long",day:"numeric"})}function t(e){const n=c(e);return n?n.toLocaleString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:!1}).replace(/\//g,"-"):"-"}export{t as a,f};
